#include <stdio.h>

#define MAX_SIZE 20
#define MAX(a,b) a > b ? a : b

int getVal(int dq[], int dq_size);
void move(int dq[], int dq_size);

int main() {
    int n;
    scanf("%d", &n);

    int ans = 0;

    for(int i=0; i<n; i++) {
        int dq[MAX_SIZE];

        for(int j = 0; j < n; j++) {
            scanf("%d", &dq[j]);
            getchar();
        }

        int max = getVal(dq, n);
        for(int j=1; j<n; j++) {
            move(dq, n);
            max = MAX(max, getVal(dq, n));
        }

        ans += max;
    }

    printf("%d\n", ans);

    return 0;
}

void move(int dq[], int dq_size) {
    int tmp = dq[0];

    for(int i=1; i<dq_size; i++) {
        dq[i-1] = dq[i];
    }

    dq[dq_size-1] = tmp;
}

int getVal(int dq[], int dq_size) {
    int ans = 0;

    for(int i=0; i<dq_size; i++) {
        ans += dq[i] * (1 << (dq_size - i - 1));
    }

    return ans;
}
